package com.khmerdubber.app

import org.junit.Assert.assertEquals
import org.junit.Test

/** Expected values generated by edge-tts 7.3.1 (Python): drm.generate_sec_ms_gec_v2(t). */
class EdgeDrmTest {
    @Test
    fun tokenMatchesPythonEdgeTts() {
        assertEquals(
            "2CD23A2CA0B2595A-F3C846C370E05F9CC83ACC5F995C5F5D87A4D0F14CE8936A0F902E64099E38A2",
            EdgeDrm.token(1700000000.0),
        )
        assertEquals(
            "67E9EE03D8740889-EE3BD4FC38A7F7EDABC199FE1B4726DB1B05768CCBBD5F524BFE6DACE4BF7063",
            EdgeDrm.token(1762560000.5),
        )
        assertEquals(
            "8BBA9E2EAAB37070-42720914045E2D94DD1FCCA47A1612405928866400779685B6BFAE8643DD4BDE",
            EdgeDrm.token(1794400123.0),
        )
        assertEquals(
            "498DEBEC091E9FBB-48F566F30D363EA955F305452BB7D7029DA9E2E43FF809AEEF3ACB5964B2A49B",
            EdgeDrm.token(2000000299.9),
        )
    }
}
